import { useCallback } from 'react';

import { useTooltipState } from './store/selectors.js';
import { useSetState } from './store/use-set-state.js';

export const useTooltip = () => {
  const setState = useSetState();
  const { pinned, visible } = useTooltipState();

  const hideTooltip = useCallback(() => {
    setState((prev) => {
      const newState = {
        ...prev,
        visible: false,
        pinned: false,
      };

      return newState;
    });
  }, [setState]);

  const showTooltip = useCallback(() => {
    setState((prev) => {
      const newState = {
        ...prev,
        visible: true,
      };

      return newState;
    });
  }, [setState]);

  const toggleTooltipPinnedState = useCallback(() => {
    setState((prev) => {
      const newState = {
        ...prev,
        pinned: !prev.pinned,
      };

      return newState;
    });
  }, [setState]);

  const hideTooltipHandler = () => {
    if (!pinned) {
      hideTooltip();
    }
  };

  const showTooltipHandler = () => {
    if (!pinned) {
      showTooltip();
    }
  };

  const toggleTooltipPinnedStateHandler = () => {
    if (visible) {
      toggleTooltipPinnedState();
    }
  };

  return {
    hideTooltip,
    hideTooltipHandler,
    showTooltip,
    showTooltipHandler,
    toggleTooltipPinnedState,
    toggleTooltipPinnedStateHandler,
  };
};
